local function submitKey(key)
    key = M.cleanKey(key)
    if key == "" then
        Library:Notify({Title="⚠️ لم يتم إدخال مفتاح", Description="يرجى إدخال مفتاحك.", Time=3})
        return
    end
    Library:Notify({Title="🔑 جارٍ التحقق", Description="جارٍ التحقق من مفتاحك...", Time=2})

    -- NEW backend: validate the key + get this game's scripts in one call.
    local data, err = M.validateKeyNew(key)
    if type(data) ~= "table" then
        local msg = "هذا المفتاح غير صالح. يرجى التحقق منه والمحاولة مرة أخرى."
        if err == "wrong_game" then
            msg = "هذا المفتاح خاص بلعبة أخرى. احصل على مفتاح لهذه اللعبة."
        elseif err == "network" or err == "no_request" then
            msg = "خطأ في الشبكة. يرجى المحاولة مرة أخرى."
        end
        Library:Notify({Title="❌ مفتاح غير صالح", Description=msg, Time=5})
        return
    end

    local scripts = data.scripts or {}
    if #scripts == 0 then
        Library:Notify({Title="🔓 المفتاح صالح", Description="لا توجد سكربتات لهذه اللعبة بعد.", Time=5})
        return
    end

    -- Valid — remember the key for next time, close this GUI, show the selector.
    M.saveKeyLocal(key)
    Library:Notify({
        Title = "🔓 المفتاح صالح",
        Description = (#scripts == 1) and "جارٍ تحميل السكربت..." or "اختر سكربتًا...",
        Time = 3,
    })
    task.wait(0.4)
    pcall(function() Library:Unload() end)
    M.showSelector(scripts)
end

local function readKeyFromBox()
    local raw
    pcall(function()
        local holder = Options and Options.KeyInput and Options.KeyInput.Holder
        local box = holder and holder:FindFirstChildOfClass("TextBox")
        if box then raw = box.Text end
    end)
    local key = M.cleanKey(raw)
    if key == "" then key = M.cleanKey(Options and Options.KeyInput and Options.KeyInput.Value) end
    if key == "" then key = M.cleanKey(keyInputValue) end
    return key
end

