FG:AddInput("FeedbackMsg", {Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = "الرسالة", Placeholder = "اكتب رسالتك (500 حرف كحد أقصى، بدون روابط)"})
local fbStatus = FG:AddLabel("", true)
FG:AddButton({
    Text = "📨 إرسال",
    Func = function()
        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            safeSet(fbStatus, string.format("يرجى الانتظار %d ثانية قبل الإرسال مرة أخرى.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback))))
            return
        end
        local ftype = tostring((Options.FeedbackType and Options.FeedbackType.Value) or "Suggestion"):lower()
        local msg   = M.trim((Options.FeedbackMsg and Options.FeedbackMsg.Value) or "")
        if msg == "" then safeSet(fbStatus, "الرسالة فارغة."); return end
        if #msg > 500 then safeSet(fbStatus, "الرسالة طويلة جدًا (500 حرف كحد أقصى)."); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            safeSet(fbStatus, "الروابط غير مسموح بها."); return
        end
        safeSet(fbStatus, "جارٍ الإرسال...")
        task.spawn(function()
            local sok, err = M.sendFeedback(ftype, msg, (preCheck and preCheck.session_token) or "")
            if sok then
                lastFeedback = tick()
                safeSet(fbStatus, "✅ تم الإرسال. شكرًا لك!")
                pcall(function() Options.FeedbackMsg:SetValue("") end)
                Library:Notify({Title = "COMBOWICK", Description = "تم إرسال ملاحظاتك. شكرًا لك!", Time = 3})
            else
                safeSet(fbStatus, ERRMAP[err] or ("فشل الإرسال: " .. tostring(err)))
            end
        end)
    end,
})
