            return
        end
        if result.disabled then
            safeSet(statusLabel, "⛔ اللعبة معطّلة")
            safeSet(hintLabel, "النسخة المجانية غير متاحة هنا. احصل على مفتاح.")
            Library:Notify({Title="COMBOWICK", Description="النسخة المجانية معطّلة لهذه اللعبة. يرجى استخدام مفتاح.", Time=6})
            return
        end
        local token = result.session_token
        if type(token) ~= "string" or #token < 20 then
            safeSet(statusLabel, "الحالة: فشل")
        else
            safeSet(statusLabel, "الحالة: تمت المصادقة")
            Library:Notify({Title="COMBOWICK", Description="تمت مصادقتك.", Time=3})
            _G.COMBOWICK_FREE   = true
            _G.COMBOWICK_ACTIVE = true
            local remaining = tonumber(result.remaining) or 0
            task.spawn(function()
                while remaining > 0 do
                    local fmt = M.formatTime(remaining)
                    safeSet(timerLabel, string.format("الوقت المتبقي: %s", fmt))
                    safeSet(lSession, string.format("وقت الجلسة: %s", fmt))
                    task.wait(1); remaining = remaining - 1
                end
                safeSet(timerLabel, "انتهت الجلسة.")
                safeSet(lSession, "وقت الجلسة: منتهٍ")
                _G.COMBOWICK_ACTIVE = false
                if M._keyPromptGui then pcall(function() M._keyPromptGui:Destroy() end); _G.COMBOWICK_KEYPROMPT = false end
                pcall(function() Library:Unload() end)
                M.showExpiredPopup(function() M.reloadExist() end)
            end)
            local scriptUrl = M.getScriptForGame(token)
            if M.loadFreeScript(scriptUrl, token) then task.wait(2); pcall(function() Library:Unload() end); pcall(M.showKeyPrompt) end
        end

    elseif result.status == "cooldown" then
        pcall(function() Tabs.Key:Show() end) --[[CDKEYTAB]]
        local remaining = tonumber(result.remaining) or 0
        safeSet(statusLabel, "في فترة انتظار")
        safeSet(hintLabel, "احصل على مفتاح لمدة 11 ساعة، أو انتظر حتى تنتهي فترة الانتظار.")
        Library:Notify({Title="COMBOWICK", Description="أنت في فترة انتظار. احصل على مفتاح لتخطي الانتظار.", Time=6})
        task.spawn(function()
            while remaining > 0 do
                local fmt = M.formatTime(remaining)
                safeSet(timerLabel, string.format("فترة الانتظار: %s", fmt))
                safeSet(lCooldown, string.format("فترة الانتظار: %s", fmt))
                task.wait(1); remaining = remaining - 1
            end
            safeSet(timerLabel, "انتهت فترة الانتظار.")
            safeSet(lCooldown, "فترة الانتظار: انتهت")
            safeSet(hintLabel, "")
            Library:Notify({Title="COMBOWICK", Description="انتهت فترة الانتظار. جارٍ إعادة التحميل...", Time=3})
            pcall(function() Library:Unload() end)
            task.wait(0.5)
            M.reloadExist()
        end)

    elseif result.status == "throttled" then
        local remaining = tonumber(result.remaining) or 0
        safeSet(statusLabel, "طلبات كثيرة جدًا")
        safeSet(hintLabel, "طلبات كثيرة جدًا. يرجى الانتظار.")
        Library:Notify({Title="COMBOWICK", Description="طلبات كثيرة جدًا. يرجى الانتظار لحظة.", Time=5})
        task.spawn(function()
            while remaining > 0 do
                safeSet(timerLabel, string.format("إعادة المحاولة خلال %s", M.formatTime(remaining)))
                task.wait(1); remaining = remaining - 1
            end
            safeSet(timerLabel, "جارٍ إعادة التحميل...")
            safeSet(hintLabel, "")
            pcall(function() Library:Unload() end)
            task.wait(0.5)
            M.reloadExist()
        end)

    elseif result.status == "disabled" then
        safeSet(statusLabel, "الخدمة متوقفة مؤقتًا")
        safeSet(hintLabel, "COMBOWICK غير متاح مؤقتًا.")
        Library:Notify({Title="COMBOWICK", Description="الخدمة معطّلة حاليًا. يرجى المحاولة لاحقًا.", Time=6})

    elseif result.status == "banned" then
        safeSet(statusLabel, "محظور")
        Library:Notify({Title="COMBOWICK", Description="أنت محظور.", Time=5})

    elseif result.status == "game_not_allowed" then
        safeSet(statusLabel, "🚫 اللعبة غير مدعومة")
        safeSet(hintLabel, "هذه اللعبة غير مدعومة بعد. مفاتيح بريميوم تعمل إذا كان هناك سكربت متاح.")
        Library:Notify({Title="COMBOWICK", Description="هذه اللعبة غير مدعومة بعد.", Time=6})

    elseif result.status == "key_required" then
        safeSet(statusLabel, "🔑 مطلوب مفتاح")
        safeSet(hintLabel, "هذه اللعبة تحتاج إلى مفتاح — أدخله في تبويب 'مفتاح بريميوم'.")
        pcall(function() Tabs.Key:Show() end)
    else
        safeSet(statusLabel, "Error")
        safeSet(hintLabel, "تعذّر الوصول إلى الخادم. يرجى تشغيل السكربت مرة أخرى.")
        Library:Notify({Title="COMBOWICK", Description=tostring(result.message or "حدث خطأ غير معروف."), Time=5})
    end
end)

local MenuGroup = Tabs.UI:AddLeftGroupbox("Menu", "wrench")
MenuGroup:AddToggle("ShowCustomCursor", {Text="مؤشر مخصص", Default=false, Callback=function(v) Library.ShowCustomCursor = v end})
MenuGroup:AddLabel("مفتاح القائمة"):AddKeyPicker("MenuKeybind", {Default="RightShift", NoUI=true, Text="مفتاح القائمة"})
MenuGroup:AddButton({Text="إلغاء التحميل", Func=function() pcall(function() Library:Unload() end) end})
Library.ToggleKeybind = Options.MenuKeybind

ThemeManager:SetLibrary(Library)
SaveManager:SetLibrary(Library)
SaveManager:IgnoreThemeSettings()
SaveManager:SetIgnoreIndexes({"MenuKeybind"})
ThemeManager:SetFolder("COMBOWICK")
SaveManager:SetFolder("COMBOWICK/game")
SaveManager:BuildConfigSection(Tabs.UI)
ThemeManager:ApplyToTab(Tabs.UI)
SaveManager:LoadAutoloadConfig()
